import { buildApp } from './app.js'
import { expectedTestLinkMcp, McpTestLinkClient } from './mcp-testlink-client.js'
import { connectToPostgres, PostgresStore } from './postgres-store.js'
import { required } from './setting.js'
import { connectToTestLinkMcp } from './stdio-tool-caller.js'

/**
 * The database, which holds the Rules and the Reference Documents. Read only
 * from here: what is in it was written by an operator with SQL, and this project
 * ships nothing that writes to it (ADR-0006).
 */
const store = new PostgresStore(await connectToPostgres(required('DATABASE_URL')))

/**
 * Read once, here, and never again — the property ADR-0004 keeps when it moves
 * Rules out of a file. A database with none enabled in it is missing in the same
 * way an invalid Rule is: there is no point starting a server that would accept
 * every write it is given.
 */
const rules = await store.rules()

if (rules.length === 0) {
  throw new Error(
    'No enabled Rules are in the database, so the server will not start. Apply schema.sql and insert a Rule — the README has the statements.',
  )
}

/**
 * How to launch testlink-mcp. It documents two ways of being run — the
 * published container and a checkout of its source — so both are reachable
 * here; the container is the default because it is the documented one. The
 * arguments are read as JSON so that a path with a space in it survives, which
 * is also the shape every MCP client configuration writes them in.
 *
 * The container is pinned to the version the client calls rather than tracking
 * `latest`. A tag is not a version: Docker will not re-pull one it already
 * holds, so `latest` is whatever it meant the first time a host pulled it, and
 * a host that pulled before a tool existed keeps a server without it.
 */
function testLinkMcp(): { command: string; args: string[] } {
  const command = process.env.TESTLINK_MCP_COMMAND

  if (command === undefined) {
    return {
      command: 'docker',
      args: [
        'run',
        '--rm',
        '-i',
        '-e',
        'TESTLINK_URL',
        '-e',
        'TESTLINK_API_KEY',
        `dogkeeper886/testlink-mcp:${expectedTestLinkMcp}`,
      ],
    }
  }

  try {
    return { command, args: JSON.parse(required('TESTLINK_MCP_ARGS')) }
  } catch (error) {
    throw new Error(
      `TESTLINK_MCP_ARGS must be a JSON list of arguments, so the server will not start: ${
        (error as Error).message
      }`,
    )
  }
}

const tools = await connectToTestLinkMcp({
  ...testLinkMcp(),
  env: {
    ...process.env,
    TESTLINK_URL: required('TESTLINK_URL'),
    TESTLINK_API_KEY: required('TESTLINK_API_KEY'),
  } as Record<string, string>,
})

const app = buildApp({
  testlink: new McpTestLinkClient(tools, { authorLogin: required('TESTLINK_AUTHOR_LOGIN') }),
  documents: store,
  rules,
  // Violations and outages, and not a line per request: what is logged is what
  // an operator is meant to read, and request logging was not asked for.
  logger: { level: 'warn' },
})

await app.listen({ port: Number(process.env.PORT ?? 3000), host: '0.0.0.0' })

import Fastify, {
  type FastifyError,
  type FastifyInstance,
  type FastifyReply,
  type FastifyRequest,
  type FastifyServerOptions,
} from 'fastify'

import type { DocumentStore } from './reference-document.js'
import { bindRules, ruleSetVersionOf, type StoredRule } from './rule-set.js'
import type {
  NewProject,
  NewTestSuite,
  ProjectChanges,
  TestCase,
  TestLinkClient,
  TestSuiteChanges,
} from './testlink-client.js'
import { findViolations, type Violation } from './violation.js'

/**
 * The Field structure of a Test Case. A submission that does not match it is
 * refused before any Rule evaluation runs. `satisfies` keeps the schema and the
 * TestCase type from drifting apart: a Field added to one must appear in both.
 */
const testCaseSchema = {
  type: 'object',
  required: ['name', 'summary'],
  additionalProperties: false,
  properties: {
    name: { type: 'string' },
    summary: { type: 'string' },
    preconditions: { type: 'string' },
  },
} as const satisfies {
  type: 'object'
  required: readonly (keyof TestCase)[]
  additionalProperties: false
  properties: Record<keyof Required<TestCase>, { type: string }>
}

/** The settings a Project carries, shared by the shapes that create and change one. */
const projectSettings = {
  notes: { type: 'string' },
  active: { type: 'boolean' },
  isPublic: { type: 'boolean' },
  requirementsEnabled: { type: 'boolean' },
  testPriorityEnabled: { type: 'boolean' },
  automationEnabled: { type: 'boolean' },
  inventoryEnabled: { type: 'boolean' },
} as const

/** What a caller says about a Project it is creating. */
const newProjectSchema = {
  type: 'object',
  required: ['name', 'prefix'],
  additionalProperties: false,
  properties: { name: { type: 'string' }, prefix: { type: 'string' }, ...projectSettings },
} as const satisfies {
  type: 'object'
  required: readonly (keyof NewProject)[]
  additionalProperties: false
  properties: Record<keyof Required<NewProject>, { type: string }>
}

/**
 * What a caller may change about a Project. At least one, because TestLink
 * refuses a change that names none and a caller reads that as its own mistake
 * sooner if it is refused here.
 */
const projectChangesSchema = {
  type: 'object',
  minProperties: 1,
  additionalProperties: false,
  properties: { name: { type: 'string' }, color: { type: 'string' }, ...projectSettings },
} as const satisfies {
  type: 'object'
  minProperties: number
  additionalProperties: false
  properties: Record<keyof Required<ProjectChanges>, { type: string }>
}

/**
 * Deleting a Project takes everything under it, so the caller restates the
 * Project's own prefix and the delete is refused without it.
 */
const deleteProjectSchema = {
  type: 'object',
  required: ['confirmPrefix'],
  additionalProperties: false,
  properties: { confirmPrefix: { type: 'string' } },
} as const

/**
 * What a caller says about a Test Suite it is creating, and where to put it.
 * Held to the same drift check as the Test Case schema above.
 */
const newTestSuiteSchema = {
  type: 'object',
  required: ['name'],
  additionalProperties: false,
  properties: {
    name: { type: 'string' },
    details: { type: 'string' },
    parentSuiteId: { type: 'string' },
  },
} as const satisfies {
  type: 'object'
  required: readonly (keyof NewTestSuite)[]
  additionalProperties: false
  properties: Record<keyof Required<NewTestSuite> | 'parentSuiteId', { type: string }>
}

/** What a caller may change about a Test Suite. Its place in the Project is not one of them. */
const testSuiteChangesSchema = {
  type: 'object',
  additionalProperties: false,
  properties: {
    name: { type: 'string' },
    details: { type: 'string' },
  },
} as const satisfies {
  type: 'object'
  additionalProperties: false
  properties: Record<keyof Required<TestSuiteChanges>, { type: string }>
}

export function buildApp({
  testlink,
  documents,
  rules,
  logger = false,
}: {
  testlink: TestLinkClient
  /** Where the Reference Documents are read from. Read only — nothing here writes one. */
  documents: DocumentStore
  /** The operator's enabled Rules, as the database holds them. Bound once here and never re-read. */
  rules: StoredRule[]
  /**
   * Where the server logs, off unless the entry point turns it on. Logs are
   * observability alone: nothing written here is read back, and no logged data
   * reaches a validation outcome.
   */
  logger?: FastifyServerOptions['logger']
}): FastifyInstance {
  // Binding happens before the server exists, so an invalid Rule leaves nothing
  // to call rather than a server running without its Rules.
  const bound = bindRules(rules)

  // Fixed for the life of the process, because the Rules are read once and
  // never reloaded.
  const ruleSetVersion = ruleSetVersionOf(rules)

  // Coercion off: a Field of the wrong type is refused, not quietly converted
  // into one that passes.
  const app = Fastify({ logger, ajv: { customOptions: { coerceTypes: false } } })

  // The envelope names the Rules this server is running, on every answer without
  // exception — a delete, which has no body to carry them, included.
  app.addHook('onSend', async (_request, reply) => {
    reply.header('Rule-Set-Version', ruleSetVersion)
  })

  /**
   * The version in the answer itself, where the Rules judged what was sent.
   * Callers are agents that read the body, so an answer the Rules took part in
   * names them in it rather than only on the envelope. An answer no Rule reached
   * — a schema refusal, or content TestLink did not hold — carries no version in
   * its body, because the Rules contributed nothing to it.
   */
  const versioned = <T extends object>(body: T) => ({ ...body, ruleSetVersion })

  /**
   * A Rejection, and the log lines that make a Rule firing over and over
   * visible — the signal separating a Rule that cannot be satisfied from an
   * agent that writes badly once. Nothing is counted here and nothing is read
   * back, so the same Test Case submitted twice is answered identically.
   */
  const reject = (request: FastifyRequest, reply: FastifyReply, violations: Violation[]) => {
    for (const { field, rule } of violations) {
      request.log.warn({ ruleSetVersion, field, rule }, 'Rule violated')
    }

    return reply.code(422).send(versioned({ violations }))
  }

  // A schema refusal carries no violations, so it cannot be read as a Rejection.
  app.setErrorHandler((error: FastifyError, _request, reply) => {
    if (error.validation) {
      return reply.code(400).send({ refusal: 'schema', message: error.message })
    }
    return reply.send(error)
  })

  /**
   * What TestLink holds nothing under is the caller's to correct, so it answers
   * as a client error — where TestLink being unreachable, which is the server's
   * to recover from, answers as a server one. Nothing was refused here, so this
   * carries no `refusal` and no violations: there was simply nothing to act on.
   */
  const nothingThere = (reply: FastifyReply, what: string) =>
    reply.code(404).send({ message: `TestLink holds no ${what}.` })

  app.post<{ Params: { projectId: string; suiteId: string }; Body: TestCase }>(
    '/projects/:projectId/suites/:suiteId/test-cases',
    { schema: { body: testCaseSchema } },
    async (request, reply) => {
      const violations = findViolations(request.body, bound.testCase)

      // A Rejection is the whole outcome: nothing is written, and the caller
      // reads a client error, where TestLink being unreachable is a server one.
      if (violations.length > 0) {
        return reject(request, reply, violations)
      }

      const { projectId, suiteId } = request.params
      const written = await testlink.createTestCase({ projectId, suiteId }, request.body)

      // Which of the two TestLink is missing is not something it says, so the
      // answer names both rather than guessing at one.
      if (written === undefined) {
        return nothingThere(reply, `Test Suite ${suiteId} in Project ${projectId}`)
      }

      return reply.code(201).send(versioned(written))
    },
  )

  app.get<{ Params: { id: string } }>('/test-cases/:id', async (request, reply) => {
    const testCase = await testlink.getTestCase(request.params.id)

    if (testCase === undefined) {
      return nothingThere(reply, `Test Case ${request.params.id}`)
    }

    // A read is never refused, whatever fired on what it serves: refusing would
    // put the content out of reach, and the caller reading it is the one who
    // needs to see what is wrong with it. The Violations sit beside the content
    // rather than in it, so what is served is what is stored.
    return reply.send(versioned({ testCase, violations: findViolations(testCase, bound.testCase) }))
  })

  // An update is a write, so the Rules run on it exactly as they run on a
  // submission. It answers with a status code of its own, so a caller knows
  // whether it added a Test Case or replaced one without reading the body.
  app.put<{ Params: { id: string }; Body: TestCase }>(
    '/test-cases/:id',
    { schema: { body: testCaseSchema } },
    async (request, reply) => {
      const violations = findViolations(request.body, bound.testCase)

      if (violations.length > 0) {
        return reject(request, reply, violations)
      }

      const applied = await testlink.updateTestCase(request.params.id, request.body)

      if (!applied) {
        return nothingThere(reply, `Test Case ${request.params.id}`)
      }

      return reply.send(versioned({ id: request.params.id }))
    },
  )

  app.delete<{ Params: { id: string } }>('/test-cases/:id', async (request, reply) => {
    const deleted = await testlink.deleteTestCase(request.params.id)

    if (!deleted) {
      return nothingThere(reply, `Test Case ${request.params.id}`)
    }

    return reply.code(204).send()
  })

  // TestLink's own structure, served straight through. No Rule binds to a
  // Project or a Test Suite — Rules are bound to the Fields of a Test Case — so
  // there is nothing here to check and nothing to attach.
  app.get('/projects', async () => testlink.listProjects())

  app.post<{ Body: NewProject }>(
    '/projects',
    { schema: { body: newProjectSchema } },
    async (request, reply) => reply.code(201).send(await testlink.createProject(request.body)),
  )

  app.put<{ Params: { projectId: string }; Body: ProjectChanges }>(
    '/projects/:projectId',
    { schema: { body: projectChangesSchema } },
    async (request, reply) => {
      const { projectId } = request.params
      const applied = await testlink.updateProject(projectId, request.body)

      if (!applied) {
        return nothingThere(reply, `Project ${projectId}`)
      }

      return reply.send({ id: projectId })
    },
  )

  app.delete<{ Params: { projectId: string }; Querystring: { confirmPrefix: string } }>(
    '/projects/:projectId',
    { schema: { querystring: deleteProjectSchema } },
    async (request, reply) => {
      const { projectId } = request.params
      const deletion = await testlink.deleteProject(projectId, request.query.confirmPrefix)

      if (deletion === 'absent') {
        return nothingThere(reply, `Project ${projectId}`)
      }

      // Nothing was deleted and nothing is wrong with TestLink: the caller
      // restated the wrong prefix, and reads that rather than an outage.
      if (deletion === 'unconfirmed') {
        return reply.code(409).send({
          message: `The prefix given does not match Project ${projectId}, so nothing was deleted.`,
        })
      }

      return reply.code(204).send()
    },
  )

  app.get<{ Params: { projectId: string }; Querystring: { parentSuiteId?: string } }>(
    '/projects/:projectId/suites',
    async (request, reply) => {
      const { projectId } = request.params
      const listed = await testlink.listTestSuites(projectId, request.query.parentSuiteId)

      if (listed === undefined) {
        return nothingThere(reply, `Project ${projectId}`)
      }

      return reply.send(listed)
    },
  )

  app.get<{ Params: { projectId: string; suiteId: string } }>(
    '/projects/:projectId/suites/:suiteId/test-cases',
    async (request, reply) => {
      const { suiteId } = request.params
      const listed = await testlink.listTestCasesInSuite(suiteId)

      if (listed === undefined) {
        return nothingThere(reply, `Test Suite ${suiteId}`)
      }

      return reply.send(listed)
    },
  )

  app.post<{ Params: { projectId: string }; Body: NewTestSuite & { parentSuiteId?: string } }>(
    '/projects/:projectId/suites',
    { schema: { body: newTestSuiteSchema } },
    async (request, reply) => {
      const { name, details, parentSuiteId } = request.body
      const { projectId } = request.params
      const created = await testlink.createTestSuite(projectId, { name, details }, parentSuiteId)

      if (created === undefined) {
        return nothingThere(reply, `Project ${projectId}`)
      }

      return reply.code(201).send(created)
    },
  )

  app.put<{ Params: { projectId: string; suiteId: string }; Body: TestSuiteChanges }>(
    '/projects/:projectId/suites/:suiteId',
    { schema: { body: testSuiteChangesSchema } },
    async (request, reply) => {
      const { projectId, suiteId } = request.params
      const applied = await testlink.updateTestSuite(projectId, suiteId, request.body)

      if (!applied) {
        return nothingThere(reply, `Test Suite ${suiteId}`)
      }

      return reply.send({ id: suiteId })
    },
  )

  // TestLink identifies a Test Suite on its own, so the Project the caller
  // named is where it is addressed from rather than part of what is deleted.
  app.delete<{ Params: { projectId: string; suiteId: string } }>(
    '/projects/:projectId/suites/:suiteId',
    async (request, reply) => {
      const deleted = await testlink.deleteTestSuite(request.params.suiteId)

      if (!deleted) {
        return nothingThere(reply, `Test Suite ${request.params.suiteId}`)
      }

      return reply.code(204).send()
    },
  )

  /**
   * The Reference Documents, which the generating agent reads instead of holding
   * files of its own. A caller names a document by its id and nothing else: no
   * path reaches this API, so there is no filesystem for a caller to describe or
   * to walk out of.
   *
   * Read only. A document the agent could write is a document it could author in
   * the style the Rules exist to catch and then read back as authority, which is
   * the same reason it cannot reload a Rule.
   */
  app.get('/reference-documents', async () => documents.listDocuments())

  app.get<{ Params: { id: string } }>('/reference-documents/:id', async (request, reply) => {
    const { id } = request.params
    const document = await documents.getDocument(id)

    // A client error, told apart from a Rejection by carrying no violations at
    // all, and from the database being unreachable — which throws, and answers
    // as a server error — by status code alone.
    if (document === undefined) {
      return reply.code(404).send({ message: `There is no Reference Document ${id}.` })
    }

    // Checked at read time, exactly as a Test Case is. This is the read path
    // ADR-0003 leaves as the only channel by which the agent sees existing
    // content, so a document carrying the wording the Rules catch says so rather
    // than teaching it on. Never refused, however much fired: refusing would put
    // the document out of reach of the caller who most needs to see what is
    // wrong with it.
    return reply.send(
      versioned({ document, violations: findViolations(document, bound.referenceDocument) }),
    )
  })

  return app
}

import { createHash } from 'node:crypto'

import type { ReferenceDocument } from './reference-document.js'
import type { TestCase } from './testlink-client.js'

/** A Field of a Test Case. */
export type TestCaseField = keyof Required<TestCase>

/** A Field of a Reference Document. */
export type ReferenceDocumentField = keyof Required<ReferenceDocument>

/** Any Field a Rule Set can be bound to, whichever content it is a part of. */
export type FieldName = TestCaseField | ReferenceDocumentField

/**
 * The Fields a Rule Set may name, per kind of content. Writing them as keys
 * makes drift a type error: a Field added to `TestCase` or to
 * `ReferenceDocument` must be added here too.
 */
const fieldNames = {
  testCase: Object.keys({
    name: null,
    summary: null,
    preconditions: null,
  } satisfies Record<TestCaseField, null>),
  referenceDocument: Object.keys({
    title: null,
    body: null,
  } satisfies Record<ReferenceDocumentField, null>),
}

/**
 * What the content is called where an operator reads it, so a report names the
 * thing the Rule Set failed to bind to rather than the key it was written under.
 */
const contentNames: Record<ContentKind, string> = {
  testCase: 'a Test Case',
  referenceDocument: 'a Reference Document',
}

/** The kinds of content Rule Sets bind to, which is what the source names first. */
export type ContentKind = keyof typeof fieldNames

function isContentKind(name: string): name is ContentKind {
  return name in fieldNames
}

/** The Rules bound to a single Field. */
export type RuleSet = Rule[]

/**
 * Every Field's Rule Set, each bound to the Field and the content it belongs
 * to. The two are kept apart rather than sharing one namespace: a Rule Set
 * written under the wrong content is then refused at startup instead of binding
 * to nothing and quietly never firing.
 */
export type RuleSets = {
  [Kind in ContentKind]: Map<FieldsOf<Kind>, RuleSet>
}

/** The Fields the named content has, as the type of its Rule Set keys. */
type FieldsOf<Kind extends ContentKind> = Kind extends 'testCase'
  ? TestCaseField
  : ReferenceDocumentField

/** One check applied to one Field. */
export type Rule = TermRule | SymbolRule

/** Matches a word or phrase, as written but in any casing. */
export interface TermRule extends RuleIdentity {
  type: 'term'
  term: string
}

/** Matches a single character, optionally only where whitespace flanks it. */
export interface SymbolRule extends RuleIdentity {
  type: 'symbol'
  symbol: string
  flanked?: 'whitespace'
}

interface RuleIdentity {
  id: string
  reason: string
  /**
   * The words and phrases that suppress this Rule where it would otherwise
   * fire, empty where it carries none. They belong to this Rule alone — there
   * is no shared exception list, because a shared list drifts away from the
   * Rules it was meant to modify.
   */
  exceptions: string[]
}

/**
 * A Rule as the database holds it — one enabled row of `rules`, carrying its
 * enabled Exceptions. The reader above speaks in these rather than in rows, so
 * the SQL stays in the store and what is bound here is what was read.
 *
 * The text is as wide as the column: `content_kind`, `field`, `category` and
 * `flanked` are constrained in `schema.sql` and narrowed again below, because a
 * type cannot be trusted about what a database answered with.
 */
export interface StoredRule {
  ruleId: string
  contentKind: string
  field: string
  category: string
  looksFor: string
  flanked: string | null
  reason: string
  exceptions: string[]
}

/**
 * Checks one stored Rule, answering either the Rule or the problem to report.
 * The Rule is rebuilt from the values that were checked, so nothing unchecked is
 * bound.
 *
 * Every problem below is already a CHECK constraint in `schema.sql`, which
 * refuses the row at insert while the operator is present to fix it. This is
 * what stands between a database those constraints were never applied to and a
 * server that binds a Rule to a Field it was not written for: it reports, and
 * the server does not start.
 */
function checkStoredRule(stored: StoredRule): Rule | string {
  const { ruleId, contentKind, field, category, looksFor, flanked, reason, exceptions } = stored
  const at = `${contentKind} / ${field} / ${ruleId === '' ? 'a Rule with no id' : ruleId}`

  if (ruleId === '') {
    return `${at}: id is missing`
  }

  if (!isContentKind(contentKind)) {
    return `${at}: Rules bind to a Test Case or a Reference Document, and this is neither`
  }

  if (!fieldNames[contentKind].includes(field)) {
    return `${at}: ${contentNames[contentKind]} has no Field by that name`
  }

  if (reason === '') {
    return `${at}: reason is missing`
  }

  const identity: RuleIdentity = { id: ruleId, reason, exceptions }

  if (category === 'term') {
    if (looksFor === '') {
      return `${at}: term must be a word or phrase, not ""`
    }

    // Flanking narrows where a character is looked for, and a Term is looked
    // for as a word already. A Term carrying it was written as one thing and
    // stored as another.
    if (flanked !== null) {
      return `${at}: flanked belongs to a Symbol Rule, not a Term Rule`
    }

    return { ...identity, type: 'term', term: looksFor }
  }

  if (category === 'symbol') {
    if ([...looksFor].length !== 1) {
      return `${at}: symbol must be a single character, not ${JSON.stringify(looksFor)}`
    }

    if (flanked === null) {
      return { ...identity, type: 'symbol', symbol: looksFor }
    }

    if (flanked !== 'whitespace') {
      return `${at}: flanked must be whitespace, not ${JSON.stringify(flanked)}`
    }

    return { ...identity, type: 'symbol', symbol: looksFor, flanked }
  }

  return `${at}: unknown rule type ${JSON.stringify(category)}`
}

/**
 * Binds stored Rules to the Field each names, or answers what is wrong with
 * them. Every problem is collected before any is reported, so an operator fixes
 * them together rather than one restart at a time.
 *
 * A Field no Rule names gets no entry, which is a Field nothing is checked
 * against — the same thing an empty Rule Set was.
 */
export function checkRules(stored: StoredRule[]): { bound: RuleSets; problems: string[] } {
  const bound: RuleSets = { testCase: new Map(), referenceDocument: new Map() }
  const problems: string[] = []

  for (const rule of stored) {
    const checked = checkStoredRule(rule)

    if (typeof checked === 'string') {
      problems.push(checked)
      continue
    }

    // `checkStoredRule` has just established that this row names one of the two
    // kinds and a Field that kind has.
    const ruleSets = bound[rule.contentKind as ContentKind] as Map<string, RuleSet>
    const ruleSet = ruleSets.get(rule.field)

    if (ruleSet === undefined) {
      ruleSets.set(rule.field, [checked])
      continue
    }

    ruleSet.push(checked)
  }

  return { bound, problems }
}

/**
 * Binds stored Rules, refusing to start where anything is wrong with them. This
 * is the startup path: there is no point starting a server that would refuse or
 * misplace every write it is given.
 */
export function bindRules(stored: StoredRule[]): RuleSets {
  const { bound, problems } = checkRules(stored)

  if (problems.length > 0) {
    refuse(problems)
  }

  return bound
}

/**
 * Refuses to start, reporting every problem at once. The message carries the
 * Field and the Rule at fault, so it is read without reading a stack trace.
 */
function refuse(problems: string[]): never {
  const report = problems.map((problem) => `  ${problem}`).join('\n')

  throw new Error(`Rule Sets are invalid, so the server will not start:\n${report}`)
}

/**
 * Names the Rules in force, so a Violation traces to the Rules that produced it
 * rather than to whichever Rules are running when it is read back. Derived from
 * the Rules themselves rather than declared beside them: a version an operator
 * types goes on naming Rules that have since been changed, which is the
 * confusion a version is kept to prevent.
 *
 * It covers everything a caller was judged by and nothing else. Disabled Rules
 * never reach here — they judge nothing — so switching one off and later back on
 * returns the version to what it was rather than to a new one meaning the same
 * thing. Neither the row's id nor the order the database answered in is part of
 * it, for the same reason: neither is something a caller was judged by.
 *
 * The Rule's own id is, though it is not looked for in a Field: it is what a
 * Violation carries, so a version that ignored it would name two Rule Sets a
 * caller reads differently as one.
 */
export function ruleSetVersionOf(stored: StoredRule[]): string {
  const canonical = stored
    .map(({ ruleId, contentKind, field, category, looksFor, flanked, reason, exceptions }) =>
      JSON.stringify([
        contentKind,
        field,
        ruleId,
        category,
        looksFor,
        flanked,
        reason,
        [...exceptions].sort(),
      ]),
    )
    .sort()
    .join('\n')

  return createHash('sha256').update(canonical).digest('hex').slice(0, 12)
}

import type { FieldName, RuleSet, SymbolRule, TermRule } from './rule-set.js'

/**
 * One Rule firing on one Field, as the caller reads it. It carries where to
 * look and why, and deliberately no replacement: the caller decides the wording,
 * and a suggestion would make this API an author rather than a check.
 */
export interface Violation {
  field: FieldName
  /** The id the operator gave the Rule, which tells two Rules on one Field apart. */
  rule: string
  reason: string
  /** The text that matched, and where it starts in the Field. */
  text: string
  offset: number
}

/**
 * Every Violation a piece of content produces. Fields are checked
 * independently, and each Field against every Rule bound to it, so the caller
 * corrects in one pass rather than resubmitting to discover the next problem.
 *
 * Written against Fields rather than against a Test Case, because a Reference
 * Document has Fields too and is checked the same way. The caller passes the
 * Rule Sets bound to that content, so a Rule can only ever reach a Field of the
 * content it was written for.
 */
export function findViolations<Field extends FieldName>(
  content: Partial<Record<Field, string>>,
  ruleSets: Map<Field, RuleSet>,
): Violation[] {
  const found: Violation[] = []

  for (const [field, rules] of ruleSets) {
    const value = content[field]

    if (value === undefined) {
      continue
    }

    for (const rule of rules) {
      const fired =
        rule.type === 'term'
          ? termViolations(field, value, rule)
          : symbolViolations(field, value, rule)

      // Suppression is applied per Rule, with only that Rule's own Exceptions,
      // so an Exception cannot reach a Rule it was not written for.
      const suppressed = suppressedSpans(value, rule.exceptions)

      found.push(...fired.filter((violation) => !isSuppressed(violation, suppressed)))
    }
  }

  return found
}

/** Where a word or phrase was found in a Field. */
interface Span {
  start: number
  end: number
}

/**
 * Where this Rule's Exceptions reach in the Field. An Exception is written the
 * way a Term is and found the same way — in any casing, however its words are
 * spaced — but it is found wherever it turns up, inside a longer word included:
 * an operator writing `guest-*` to permit a wildcard SSID means the characters
 * they wrote, and a Rule that fires on `guest-*1` has not been excepted.
 */
function suppressedSpans(value: string, exceptions: string[]): Span[] {
  return exceptions.flatMap((exception) => spansOf(value, exception))
}

/**
 * Whether an Exception covers the whole of what the Rule matched. Suppression
 * is by where the match falls, not by what the Field contains elsewhere: an
 * Exception permits the narrow case it names and leaves the rest of the Field
 * under the Rule.
 */
function isSuppressed(violation: Violation, spans: Span[]): boolean {
  const { offset, text } = violation

  return spans.some((span) => offset >= span.start && offset + text.length <= span.end)
}

/** Every place a Term Rule fires in one Field. */
function termViolations(field: FieldName, value: string, rule: TermRule): Violation[] {
  const found: Violation[] = []

  for (const { start, end } of spansOf(value, rule.term)) {
    // The casing found, not the casing the Rule was written in, so the caller
    // can locate the text in the Field it submitted.
    const text = value.slice(start, end)

    if (!standsAsWord(value, start, text)) {
      continue
    }

    found.push({ field, rule: rule.id, reason: rule.reason, text, offset: start })
  }

  return found
}

/** Every place a word or phrase turns up in a Field, as a Term is read. */
function spansOf(value: string, phrase: string): Span[] {
  const spans: Span[] = []

  for (const match of value.matchAll(matcherFor(phrase))) {
    spans.push({ start: match.index, end: match.index + match[0].length })
  }

  return spans
}

/**
 * Finds a word or phrase as written but in any casing: an operator bans a word once,
 * rather than once per capitalisation the word turns up in. A Field is free text
 * an agent wrote, so the words of a phrase are found however they are spaced —
 * a Term a line break defeats is a Term that does not hold.
 */
function matcherFor(term: string): RegExp {
  const literal = term.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')

  return new RegExp(literal.replace(/\s+/g, '\\s+'), 'giu')
}

/**
 * Whether the match stands as a word rather than sitting inside a longer one.
 * This is what separates a Term from a Symbol: banning `utilise` leaves
 * `utilises` alone, where banning a character finds it anywhere.
 */
function standsAsWord(value: string, offset: number, text: string): boolean {
  return isOutsideAWord(value[offset - 1]) && isOutsideAWord(value[offset + text.length])
}

/**
 * Anything a word does not run through, the edge of the Field included. A word
 * runs through a hyphen and an underscore, so banning `associates` leaves
 * `re-associates` alone — the same reading of a word the Symbol Rules take.
 */
function isOutsideAWord(character: string | undefined): boolean {
  return character === undefined || !/[\p{L}\p{N}_-]/u.test(character)
}

/** Every place a Symbol Rule fires in one Field. */
function symbolViolations(field: FieldName, value: string, rule: SymbolRule): Violation[] {
  const found: Violation[] = []
  const { symbol } = rule

  for (
    let offset = value.indexOf(symbol);
    offset !== -1;
    offset = value.indexOf(symbol, offset + symbol.length)
  ) {
    if (rule.flanked === 'whitespace' && !flankedByWhitespace(value, offset, symbol)) {
      continue
    }

    found.push({ field, rule: rule.id, reason: rule.reason, text: symbol, offset })
  }

  return found
}

/**
 * Whether whitespace surrounds the Symbol. The edge of the Field counts as
 * whitespace: a Symbol opening or closing a Field is filler punctuation in the
 * same way one mid-sentence is, and it is still not inside a word.
 */
function flankedByWhitespace(value: string, offset: number, symbol: string): boolean {
  return isGap(value[offset - 1]) && isGap(value[offset + symbol.length])
}

/** Whitespace, or the edge of the Field. */
function isGap(character: string | undefined): boolean {
  return character === undefined || /\s/.test(character)
}

import pg from 'pg'

import type { Queries } from './queries.js'
import type {
  DocumentStore,
  ListedReferenceDocument,
  ReferenceDocument,
} from './reference-document.js'
import type { StoredRule } from './rule-set.js'

/**
 * Whether an operator has applied `schema.sql` to this database. Asked outright
 * rather than read out of the error a missing table would raise: absence is told
 * from unreachability by what the database says about itself, never by matching
 * the text of a failure.
 */
async function hasSchema(queries: Queries): Promise<boolean> {
  const rows = await queries.run(
    "select 1 from information_schema.tables where table_name = 'rules'",
  )

  return rows.length > 0
}

/**
 * The enabled Exceptions, gathered under the Rule each belongs to. Read in a
 * statement of its own rather than joined: a Rule with no Exception is the
 * common one, and a join would answer for it with a row of nulls to tell apart
 * from a row carrying a phrase.
 */
async function exceptionsByRule(queries: Queries): Promise<Map<number, string[]>> {
  const rows = await queries.run(
    'select rule, phrase from rule_exceptions where enabled order by id',
  )
  const byRule = new Map<number, string[]>()

  for (const row of rows) {
    const rule = Number(row.rule)
    const phrases = byRule.get(rule)

    if (phrases === undefined) {
      byRule.set(rule, [String(row.phrase)])
      continue
    }

    phrases.push(String(row.phrase))
  }

  return byRule
}

/**
 * The database, read only. This project makes no write to it at all (ADR-0006),
 * so there is no method here that could relax a Rule or author a Reference
 * Document — the server holds an object that cannot do either.
 *
 * Absence is an answer rather than a failure: a document the database holds
 * nothing under answers `undefined`, where the database being unreachable
 * throws out of `pg` and reaches the caller as a server error.
 */
export class PostgresStore implements DocumentStore {
  constructor(private readonly queries: Queries) {}

  /**
   * The enabled Rules, each carrying its enabled Exceptions. Read once at
   * startup and never again, which is the property ADR-0004 keeps: a running
   * server judges every Test Case by the Rules it started with.
   *
   * A disabled Rule is not read at all. It stops firing exactly as completely as
   * a deleted one would, and its row stays so a Violation logged against it can
   * still be explained (ADR-0007).
   *
   * A database the schema has never been applied to has no tables at all, which
   * is still "no Rules" and not an outage — so it answers none here and the
   * server says what to do, rather than dying on a missing table.
   */
  async rules(): Promise<StoredRule[]> {
    if (!(await hasSchema(this.queries))) {
      return []
    }

    const rows = await this.queries.run(
      'select id, rule_id, content_kind, field, category, looks_for, flanked, reason from rules where enabled order by id',
    )
    const exceptions = await exceptionsByRule(this.queries)

    return rows.map((row) => ({
      ruleId: String(row.rule_id),
      contentKind: String(row.content_kind),
      field: String(row.field),
      category: String(row.category),
      looksFor: String(row.looks_for),
      // The column is nullable, and only a Symbol Rule ever carries it.
      flanked: row.flanked === null || row.flanked === undefined ? null : String(row.flanked),
      reason: String(row.reason),
      exceptions: exceptions.get(Number(row.id)) ?? [],
    }))
  }

  async listDocuments(): Promise<ListedReferenceDocument[]> {
    const rows = await this.queries.run('select id, title from reference_documents order by id')

    return rows.map((row) => ({ id: String(row.id), title: String(row.title) }))
  }

  async getDocument(id: string): Promise<ReferenceDocument | undefined> {
    const [row] = await this.queries.run(
      'select title, body from reference_documents where id = $1',
      [id],
    )

    return row === undefined ? undefined : { title: String(row.title), body: String(row.body) }
  }
}

/** What this project needs of a connected client, which is one method of it. */
interface Connected {
  query(sql: string, parameters?: unknown[]): Promise<{ rows: unknown[] }>
}

/**
 * Puts a connected client behind the statements-and-rows seam everything above
 * speaks in. Exported so that a test running an in-process Postgres reaches it
 * through this same adapter rather than through a copy of it.
 */
export function queriesFrom(client: Connected): Queries {
  return {
    async run(sql: string, parameters?: unknown[]) {
      const { rows } = await client.query(sql, parameters)
      return rows as Record<string, unknown>[]
    },
  }
}

/**
 * Opens the one connection this process needs. Narrow by design: everything
 * above it speaks in statements and rows, so the store is exercised without a
 * database and this is the only part that needs one.
 */
export async function connectToPostgres(url: string): Promise<Queries & { close(): Promise<void> }> {
  const client = new pg.Client({ connectionString: url })

  await client.connect()

  return { ...queriesFrom(client), close: () => client.end() }
}

