import { Client } from '@modelcontextprotocol/sdk/client/index.js'
import { StdioClientTransport } from '@modelcontextprotocol/sdk/client/stdio.js'

import type { ToolCaller, ToolResult } from './tool-caller.js'

/**
 * Speaks to a testlink-mcp process over stdio. testlink-mcp answers in text
 * whether a call worked or not, so all this does is put that text and the one
 * structural signal beside it in reach of the client above — every reading of
 * what TestLink said happens there, where it can be exercised without a process.
 */
export async function connectToTestLinkMcp(server: {
  command: string
  args: string[]
  env: Record<string, string>
}): Promise<ToolCaller> {
  const client = new Client({ name: 'testcase-validator', version: '0.0.0' })

  await client.connect(new StdioClientTransport(server))

  return {
    async call(tool: string, args: Record<string, unknown>): Promise<ToolResult> {
      const result = await client.callTool({ name: tool, arguments: args })

      return { text: textOf(result.content), isError: result.isError === true }
    },
  }
}

/** What testlink-mcp said, which it says as text and nothing else. */
function textOf(content: unknown): string {
  if (!Array.isArray(content)) {
    return ''
  }

  return content
    .filter((part): part is { type: 'text'; text: string } => part?.type === 'text')
    .map((part) => part.text)
    .join('')
}

